using UnityEngine;

namespace Astrea;

[CreateAssetMenu(fileName = "CharacterUnlockedAchievementDataHiddenHandler", menuName = "Data/Achievements/CharacterUnlockedAchievementDataHiddenHandler")]
public class CharacterUnlockedAchievementDataHiddenHandler : AchievementDataHiddenHandler
{
	[SerializeField]
	protected Character character;

	public override bool IsHidden()
	{
		return !character.CharacterProgression.CharacterUnlocked;
	}
}
